command:
cat > "$TMPDIR/apply-203-spec.mjs" <<'EOF'
// APRV-203 SPEC section 10.1 amendments, verbatim from the task notes.
// Usage: node apply-203-spec.mjs <repo-root> SPEC.md
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
const [root, declared] = process.argv.slice(2);
if (!root || declared !== 'SPEC.md') throw new Error('usage: node apply-203-spec.mjs <repo-root> SPEC.md');
const p = join(root, 'SPEC.md');
let t = readFileSync(p, 'utf8');
function once(a, b, label) { const i = t.indexOf(a); if (i < 0) throw new Error(label + ': anchor not found'); if (t.indexOf(a, i + 1) >= 0) throw new Error(label + ': anchor not unique'); t = t.slice(0, i) + b + t.slice(i + a.length); }
once(
  '`log advance` verifies the chain, stages exactly the log, the queue projection, and the payload store, refusing when any other path is staged rather than unstaging it; commits on the currently checked-out branch with the sequence range in the message; and pushes that commit to a records branch. It MUST NOT check anything out: a branch switch with an uncommitted log rewinds the log file underneath its appender.\n',
  '`log advance` verifies the chain, refuses when any path other than the log, the queue projection and the payload store is staged, fetches the base branch, and builds its commit on the REMOTE\'s tip rather than on the local branch\'s: a scratch index is filled from that tree, the three paths are laid over it from the working tree, and the commit is parented on the remote and pushed to a records branch by refspec. It MUST NOT check anything out and MUST NOT move the operator\'s branch, index or working tree: a branch switch with an uncommitted log rewinds the log file underneath its appender, and a stale local tip produced records commits that reverted whatever the remote had merged since. A local branch carrying commits the remote does not have is not a refusal, since the commit is parented on the remote either way. A working log the remote\'s log is not a prefix of IS refused, in both directions, each with its own machine-readable code. (Amended APRV-203, pending sign-off.)\n',
  'log advance paragraph');
once(
  'and the policy edit stays in the working tree.\n',
  'and the policy edit stays in the working tree.\n\nThe ceremony owns its own git preconditions. It fetches the remote, refuses unless the remote\'s policy bytes are the attested baseline the edit was written against and the remote\'s log is a prefix of the working log, runs the policy\'s declared expectation set against the amended file where one exists, and only then attests. Each of those refusals is machine-readable, distinct, and reached before the attestation, so a stopped ceremony leaves the policy edit as a working-tree change and nothing else. The commit is assembled on the remote\'s tip without a checkout and pushed by refspec, so the human ends the ceremony on the branch they started on with the working tree they started with. (Amended APRV-203, pending sign-off.)\n',
  'policy amend paragraph');
writeFileSync(p, t);
console.log('applied: SPEC.md section 10.1 (log advance paragraph replaced, policy amend paragraph extended)');
EOF
mkdir -p "$TMPDIR/dry203" && cp SPEC.md "$TMPDIR/dry203/" && node "$TMPDIR/apply-203-spec.mjs" "$TMPDIR/dry203" SPEC.md && diff SPEC.md "$TMPDIR/dry203/SPEC.md" | grep -c '^[<>]'
